#!/usr/bin/env python3
"""Remove generated Python and test-cache files from this practice workspace.

Usage:
    python scripts/cleanup_generated.py          # preview removals
    python scripts/cleanup_generated.py --apply  # remove them
"""

from __future__ import annotations

import argparse
import shutil
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent

# Directory names that are safe to remove when generated by local tooling.
CACHE_DIRECTORIES = {
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".hypothesis",
}

# Compiled Python files can also appear outside __pycache__ directories.
COMPILED_SUFFIXES = {".pyc", ".pyo"}


def find_generated_paths() -> list[Path]:
    paths: list[Path] = []

    for path in ROOT.rglob("*"):
        if ".git" in path.parts or ".venv" in path.parts or "venv" in path.parts:
            continue
        if path.is_dir() and path.name in CACHE_DIRECTORIES:
            paths.append(path)
        elif path.is_file() and path.suffix in COMPILED_SUFFIXES:
            paths.append(path)

    # A cache directory contains compiled files, so do not return both the
    # directory and its children. Removing the directory once avoids stale
    # paths after shutil.rmtree() has already deleted those children.
    directories = {path for path in paths if path.is_dir()}
    paths = [
        path
        for path in paths
        if not any(parent in directories for parent in path.parents)
    ]

    return sorted(paths)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--apply",
        action="store_true",
        help="actually remove generated files; without this flag, only preview them",
    )
    args = parser.parse_args()

    paths = find_generated_paths()
    if not paths:
        print("No generated cache files found.")
        return 0

    action = "Removing" if args.apply else "Would remove"
    for path in paths:
        print(f"{action}: {path.relative_to(ROOT)}")
        if args.apply:
            if path.is_dir():
                shutil.rmtree(path)
            else:
                path.unlink()

    if not args.apply:
        print(f"\nPreview only: {len(paths)} paths found. Re-run with --apply to remove them.")
    else:
        print(f"\nRemoved {len(paths)} generated paths.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
